1	/** Immutable SetupBench adapter entry point for one Ada attempt.
2	 *  Copy of setupbench_ada_runner.ts whose only change is a `ts` (epoch ms) on every trace entry,
3	 *  for per-turn latency. The original stays byte-identical to the runner R1-R10 recorded. */
4	import { appendFileSync, writeFileSync } from "node:fs";
5	import { readFile } from "node:fs/promises";
6	import { resolve } from "node:path";
7	import { ClaudeAgentSession } from "/opt/ada/agent/claude/agent.ts";
8	import { resolveModel } from "/opt/ada/agent/config/model.ts";
9	import { systemPromptGuidance } from "/opt/ada/agent/system-guidance.ts";
10	import type { ResultEvent, StreamJsonEvent } from "/opt/ada/agent/types/streamjson.ts";
11	
12	const [workspaceArg, promptFileArg] = process.argv.slice(2);
13	if (!workspaceArg || !promptFileArg) {
14	  throw new Error("usage: node setupbench_ada_runner.ts WORKSPACE PROMPT_FILE");
15	}
16	
17	const cwd = resolve(workspaceArg);
18	const prompt = await readFile(resolve(promptFileArg), "utf8");
19	let result: ResultEvent | null = null;
20	const tracePath = "/testbed/.ada-trace.jsonl";
21	writeFileSync(tracePath, "", "utf8");
22	
23	function bounded(value: unknown, max = 4000): unknown {
24	  if (typeof value === "string") return value.length > max ? `${value.slice(0, max)}...[truncated]` : value;
25	  const rendered = JSON.stringify(value);
26	  if (rendered.length <= max) return value;
27	  return `${rendered.slice(0, max)}...[truncated]`;
28	}
29	
30	function normalize(event: StreamJsonEvent): unknown | null {
31	  if (event.type === "assistant") {
32	    return {
33	      type: event.type,
34	      content: event.message.content.map((block) => {
35	        if (block.type === "text") return { type: block.type, text: bounded(block.text) };
36	        if (block.type === "thinking") return { type: block.type, thinking: bounded(block.thinking, 2000) };
37	        if (block.type === "tool_use") return { type: block.type, name: block.name, input: bounded(block.input) };
38	        return { type: block.type };
39	      }),
40	      usage: event.message.usage,
41	    };
42	  }
43	  if (event.type === "user") {
44	    return {
45	      type: event.type,
46	      content: event.message.content.map((block) =>
47	        block.type === "tool_result"
48	          ? { type: block.type, is_error: block.is_error, content: bounded(block.content) }
49	          : { type: block.type },
50	      ),
51	    };
52	  }
53	  if (event.type === "system") {
54	    if (event.subtype !== "init" && event.subtype !== "api_retry") return null;
55	    return { type: event.type, subtype: event.subtype, error: bounded((event as { error?: unknown }).error ?? "") };
56	  }
57	  if (event.type === "result") return event;
58	  return null;
59	}
60	
61	await new Promise<void>((resolveRun, rejectRun) => {
62	  const source = new ClaudeAgentSession({
63	    model: resolveModel(),
64	    allowedTools: ["Read", "Edit", "Write", "Bash", "Grep", "Glob"],
65	    permissionMode: "acceptEdits",
66	    cwd,
67	    userId: "autoresearch-setupbench",
68	    systemPromptAppend: systemPromptGuidance({ configured: false, connected: false }),
69	  });
70	  source.on("event", (event) => {
71	    if (event.type === "result") result = event as ResultEvent;
72	    const item = normalize(event);
73	    if (item !== null) appendFileSync(tracePath, `${JSON.stringify({ ts: Date.now(), ...(item as object) })}\n`, "utf8");
74	  });
75	  source.once("spawnError", rejectRun);
76	  source.once("exit", (code) => {
77	    if (code === 0) resolveRun();
78	    else rejectRun(new Error(`Ada agent exited ${code}`));
79	  });
80	  source.start();
81	  source.sendUserMessage(prompt);
82	  source.closeInput();
83	});
84	
85	console.log(`ADA_RUN_RESULT=${JSON.stringify(result)}`);
86
